    "template": "<html lang='en'><head><meta charset='utf-8' /><title>Certificate of Completion</title><meta name='viewport' content='width=device-width, initial-scale=1' /><style>*{margin:0;padding:0;box-sizing:border-box}@page{size:A4 landscape;margin:15mm}body{font-family:'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif;margin:0;padding:0;background:#fff;print-color-adjust:exact;-webkit-print-color-adjust:exact}.outer-border{width:100%;height:100vh;padding:15px;text-align:center;border:20px solid #d4b56a;font-family:'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif;margin:0;display:flex;flex-direction:column;box-sizing:border-box;background:#fff}.inner-border{padding:25px;text-align:center;border:4px solid #d4b56a;flex:1;display:flex;flex-direction:column;box-sizing:border-box;position:relative;background:#fff}.inner-border::before{content:'';position:absolute;top:8px;left:8px;right:8px;bottom:8px;border:2px solid #d4b56a;pointer-events:none}.inner-border::after{content:'';position:absolute;top:15px;left:15px;right:15px;bottom:15px;border:1px solid #d4b56a;pointer-events:none;box-shadow:inset 0 0 15px rgba(212,181,106,0.15)}.content{position:relative;flex:1;display:flex;flex-direction:column;z-index:1;padding:10px 0}.logo{height:60px;width:auto;margin:0 auto 12px;border-radius:0;display:block;object-fit:contain}.title{font-size:44px;font-weight:700;color:#1f5fbf;margin:8px 0 24px}.body{font-size:18px;color:#333;max-width:820px;margin:0 auto 32px;line-height:1.7;flex:1}.body>div{margin:8px 0}.recipient{font-size:28px;font-weight:700;margin:18px 0;color:#222}.meta{font-weight:600;margin-top:24px;color:#444;font-size:16px}.footer{margin-top:auto;display:flex;align-items:flex-end;justify-content:space-between;gap:20px;padding:30px 40px 0;flex-shrink:0;width:100%;min-height:fit-content}.sign-blocks{display:flex;gap:40px;align-items:flex-end;justify-content:flex-start}.sign{text-align:left;min-width:220px}.sign .name{font-size:14px;font-weight:700;margin-bottom:4px;color:#222}.sign .designation{font-size:12px;color:#666}.verify{text-align:right;font-size:12px;color:#666;flex-shrink:0;display:flex;flex-direction:column;align-items:flex-end;justify-content:flex-end}@media print{*{print-color-adjust:exact;-webkit-print-color-adjust:exact}body{height:210mm;width:297mm;margin:0;padding:0;overflow:visible}.outer-border{width:297mm;height:210mm;min-height:210mm;max-height:210mm;padding:12px;border:18px solid #d4b56a;page-break-after:avoid;page-break-inside:avoid;margin:0}.inner-border{padding:20px;border:4px solid #d4b56a}.content{height:100%;overflow:visible}}</style></head><body><div class='outer-border'><div class='inner-border'><div class='content'><img class='logo' alt='Issuer Logo' src='https://sunbird.org/images/sunbird-logo-new.png' /><div class='title'>Academic Attestation Certificate</div><div class='body'><div>This is to formally certify that</div><div class='recipient'>{{fullName}}</div><div>is a student of <strong>{{instituteName}}</strong></div><div>Degree Awarded: <strong>{{degree}}</strong></div><div>Grade Achieved: <strong>{{grade}}</strong></div><div style='margin-top:18px;'>This attestation is issued by the institute acknowledging the authenticity of the above academic details.</div></div><div class='footer'><div class='sign-blocks'><div class='sign'><div class='designation'>Scan to verify</div></div></div><div class='verify'><div style='width:110px;height:110px;border:1px dashed #ddd;margin:0 0 8px 0;display:flex;align-items:center;justify-content:center;'><img src='{{qr}}' alt='QR Code' style='width:100%;height:100%;object-fit:contain;' /></div><div>Authorized Signatory</div></div></div></div></div></div></body></html>",
    "type": "Handlebar"
}

